// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }
    const t = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(t);
      reject(signal.reason);
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

function withAbortRace(promise, signal) {
  if (!signal) {
    return promise;
  }
  if (signal.aborted) {
    return Promise.reject(signal.reason);
  }
  let onAbort;
  const abortPromise = new Promise((_, reject) => {
    onAbort = () => reject(signal.reason);
    signal.addEventListener('abort', onAbort, { once: true });
  });
  return Promise.race([promise, abortPromise]).finally(() => {
    signal.removeEventListener('abort', onAbort);
  });
}

function sleepWithAbort(sleep, ms, signal) {
  if (!signal) {
    try {
      return Promise.resolve(sleep(ms, signal));
    } catch (e) {
      return Promise.reject(e);
    }
  }
  if (signal.aborted) {
    return Promise.reject(signal.reason);
  }
  let sleepPromise;
  try {
    sleepPromise = Promise.resolve(sleep(ms, signal));
  } catch (e) {
    return Promise.reject(e);
  }
  return withAbortRace(sleepPromise, signal);
}

export async function retry(fn, opts = {}) {
  const {
    retries = 3,
    baseDelayMs = 100,
    factor = 2,
    sleep = defaultSleep,
    signal,
  } = opts;

  if (signal?.aborted) {
    throw signal.reason;
  }

  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (signal?.aborted) {
      throw signal.reason;
    }
    try {
      let fnPromise;
      try {
        fnPromise = Promise.resolve(fn(attempt));
      } catch (e) {
        fnPromise = Promise.reject(e);
      }
      const result = await withAbortRace(fnPromise, signal);
      if (signal?.aborted) {
        throw signal.reason;
      }
      return result;
    } catch (err) {
      if (signal?.aborted) {
        throw signal.reason;
      }
      if (err && err.retryable === false) {
        throw err;
      }
      lastErr = err;
      if (attempt === retries) {
        break;
      }
      if (signal?.aborted) {
        throw signal.reason;
      }
      const delay = baseDelayMs * Math.pow(factor, attempt);
      try {
        await sleepWithAbort(sleep, delay, signal);
      } catch (sleepErr) {
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw sleepErr;
      }
    }
  }
  throw lastErr;
}

