/**
 * @param {Array<{ sku: string, qty: number, unitCents: number }>} lines
 * @param {{ taxBps: number }} opts  tax rate in basis points (2000 = 20%)
 */
export function buildInvoice(lines, { taxBps }) {
  if (!Number.isInteger(taxBps) || taxBps < 0) throw new RangeError('taxBps must be a non-negative integer');

  function taxCentsFor(netCents, bps) {
    if (Number.isInteger(netCents)) {
      try {
        const bigNet = BigInt(netCents);
        const bigBps = BigInt(bps);
        const bigN = bigNet * bigBps;
        const D = 10000n;
        const sign = bigN < 0n ? -1n : 1n;
        const absN = bigN < 0n ? -bigN : bigN;
        const quot = absN / D;
        const rem = absN % D;
        if (rem < 5000n) return Number(sign * quot);
        if (rem > 5000n) return Number(sign * (quot + 1n));
        // exactly half -> round to even
        return Number(sign * (quot % 2n === 0n ? quot : quot + 1n));
      } catch {
        // fall through to floating path if BigInt conversion fails
      }
    }
    // Floating path for non-integer netCents
    const x = (netCents * bps) / 10000;
    const sign = x < 0 ? -1 : 1;
    const abs = Math.abs(x);
    const floor = Math.floor(abs);
    const frac = abs - floor;
    const eps = 1e-12;
    if (Math.abs(frac - 0.5) < eps) {
      return sign * (floor % 2 === 0 ? floor : floor + 1);
    }
    return sign * Math.round(abs);
  }

  const out = lines.map((l) => {
    const netCents = l.qty * l.unitCents;
    const taxCents = taxCentsFor(netCents, taxBps);
