  return {
    cache,
    async getUser(id) {
      return cache.getOrLoad(`user:${id}`, () => api.fetchUser(id));
    },
    /** Synchronous peek used by the request logger; must never return a promise. */
    peekUser(id) {
      return cache.get(`user:${id}`);
    },
    invalidate(id) {
      cache.delete(`user:${id}`);
    },
  };
