import { defaults, deepMerge, isKnownLeaf, getPath, setPath, coerce } from './schema.mjs';
import { parseEnv } from './env.mjs';
import { parseArgs } from './cli.mjs';

/** Keep only keys from the config file that exist in the schema. */
function pickKnown(file, prefix = '') {
  const out = {};
  let entries;
  try {
    entries = Object.entries(file ?? {});
  } catch {
    return out;
  }
  for (const [k, v] of entries) {
    try {
      const path = prefix ? `${prefix}.${k}` : k;
      if (v && typeof v === 'object' && !Array.isArray(v)) {
        let def;
        try {
          def = getPath(defaults, path);
        } catch {
          def = undefined;
        }
        if (def && typeof def === 'object') {
          const sub = pickKnown(v, path);
          if (Object.keys(sub).length) {
            try {
              setPath(out, path.split('.').at(-1), sub);
            } catch {}
          }
        }
      } else {
        try {
          if (isKnownLeaf(path)) {
            out[k] = v;
          }
        } catch {}
      }
    } catch {
      continue;
    }
  }
  return out;
}

function parseCli(argv = []) {
  let flat;
  try {
    flat = parseArgs(argv);
  } catch {
    return {};
  }
  const out = {};
  if (!flat || typeof flat !== 'object') return out;
  let entries;
  try {
    entries = Object.entries(flat);
  } catch {
    return out;
  }
  for (const [path, raw] of entries) {
    try {
      if (!isKnownLeaf(path)) continue;
      const coerced = coerce(path, raw);
      if (coerced === undefined) continue;
      setPath(out, path, coerced);
    } catch {
      continue;
    }
  }
  return out;
}

/**
 * Resolve configuration.
 * @param {{ file?: object, env?: Record<string,string>, argv?: string[] }} sources
 */
export function loadConfig({ file = {}, env = {}, argv = [] } = {}) {
  let cfg;
  try {
    cfg = JSON.parse(JSON.stringify(defaults));
  } catch {
    try {
      cfg = deepMerge({}, defaults);
      if (cfg.db && cfg.db === defaults.db) {
        try {
          cfg = { ...cfg, db: { ...cfg.db } };
        } catch {}
      }
    } catch {
      cfg = {
        port: 3000,
        debug: false,
        logLevel: 'info',
        db: { host: 'localhost', port: 5432, pool: 5, ssl: false },
      };
    }
  }

  try {
    const knownFile = pickKnown(file);
    try {
      cfg = deepMerge(cfg, knownFile);
    } catch {}
  } catch {}

  try {
    const envCfg = parseEnv(env);
    try {
      cfg = deepMerge(cfg, envCfg);
    } catch {}
  } catch {}

  try {
    const cliCfg = parseCli(argv);
    try {
      cfg = deepMerge(cfg, cliCfg);
    } catch {}
  } catch {}

  return cfg;
}

